55	// runElections lists elections, in force first, then superseded.
56	func runElections(ctx context.Context, lg *ledger.Ledger, args []string, out io.Writer) error {
57		all, err := lg.Elections(ctx)
58		if err != nil {
59			return err
60		}
61		tw := tabwriter.NewWriter(out, 0, 4, 2, ' ', 0)
62		fmt.Fprintln(tw, "ID\tKIND\tABOUT\tVALUE\tMADE\tSTATUS")
63		for _, e := range all {
64			status := "in force"
65			if e.SupersededBy != 0 {
66				status = fmt.Sprintf("superseded by %d", e.SupersededBy)
67			}
68			fmt.Fprintf(tw, "%d\t%s\t%s\t%s\t%s\t%s\n", e.ID, e.Kind, e.About, e.Summary(), e.MadeAt.Format("2006-01-02"), status)
69		}
70		return tw.Flush()
71	}
